import React, { useState, useEffect } from 'react';
import { Card, Button, Select, api } from '../App';

export default function ReportsPage() {
  const [saleNos, setSaleNos] = useState([]);
  const [saleNo,  setSaleNo]  = useState('');
  const [summary, setSummary] = useState([]);
  const [byGarden, setByGarden] = useState([]);
  const [tab, setTab] = useState('party');

  useEffect(() => {
    api.get('/import/sale-numbers').then(r => setSaleNos(r.data));
  }, []);

  const load = async () => {
    const params = saleNo ? `?sale_no=${saleNo}` : '';
    const [s, g] = await Promise.all([
      api.get(`/reports/summary${params}`),
      api.get(`/reports/by-garden${params}`)
    ]);
    setSummary(s.data);
    setByGarden(g.data);
  };

  const fmt = v => v !== undefined && v !== null ? Number(v).toFixed(2) : '—';
  const fmtN = v => v !== undefined && v !== null ? Number(v).toFixed(0) : '—';

  return (
    <div>
      <h2 style={{ marginBottom:6, color:'#1a3c5e' }}>📋 Reports</h2>
      <p style={{ color:'#888', fontSize:13, marginBottom:20 }}>View marking summaries by party or garden for any sale.</p>

      <Card>
        <div style={{ display:'flex', gap:12, alignItems:'flex-end' }}>
          <div style={{ minWidth:220 }}>
            <Select label="Sale Number" value={saleNo} onChange={setSaleNo} placeholder="All sales"
              options={saleNos.map(s => ({ value: s.sale_no, label: s.sale_no }))} />
          </div>
          <Button onClick={load} style={{ marginBottom:14 }}>📊 Generate Report</Button>
        </div>
      </Card>

      {/* Tabs */}
      <div style={{ display:'flex', gap:0, marginBottom:0 }}>
        {['party','garden'].map(t => (
          <button key={t} onClick={() => setTab(t)}
            style={{
              padding:'8px 20px', border:'none', cursor:'pointer', fontSize:13, fontWeight:600,
              background: tab===t ? '#1a3c5e' : '#e2e8f0',
              color: tab===t ? '#fff' : '#555',
              borderRadius: t==='party' ? '8px 0 0 0' : '0 8px 0 0'
            }}>
            {t === 'party' ? '🏢 By Party' : '🌿 By Garden'}
          </button>
        ))}
      </div>

      {tab === 'party' && (
        <Card style={{ borderRadius:'0 8px 8px 8px', marginTop:0 }}>
          {summary.length === 0 ? (
            <div style={{ padding:24, textAlign:'center', color:'#aaa' }}>Click Generate Report to load data</div>
          ) : (
            <div style={{ overflowX:'auto' }}>
              <table style={{ width:'100%', borderCollapse:'collapse', fontSize:13 }}>
                <thead>
                  <tr style={{ background:'#f0f4f8' }}>
                    {['Party','Code','Lots','Bags','Net Wt (kg)','Avg Price','Min Price','Max Price','Labels Printed','Confirmed','Skipped'].map(h => (
                      <th key={h} style={{ padding:'8px 10px', textAlign:'left', fontWeight:600, borderBottom:'2px solid #e2e8f0', whiteSpace:'nowrap' }}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {summary.map((r, i) => (
                    <tr key={i} style={{ borderBottom:'1px solid #f0f4f8', background: i%2===0?'#fff':'#fafbfc' }}>
                      <td style={{ padding:'7px 10px', fontWeight:600 }}>{r.party_name}</td>
                      <td style={{ padding:'7px 10px', color:'#888' }}>{r.party_code}</td>
                      <td style={{ padding:'7px 10px' }}>{r.total_lots}</td>
                      <td style={{ padding:'7px 10px' }}>{fmtN(r.total_bags)}</td>
                      <td style={{ padding:'7px 10px' }}>{fmtN(r.total_net_wt)}</td>
                      <td style={{ padding:'7px 10px', fontWeight:600, color:'#1a3c5e' }}>₹{fmt(r.avg_price)}</td>
                      <td style={{ padding:'7px 10px', color:'#1a7a4a' }}>₹{fmt(r.min_price)}</td>
                      <td style={{ padding:'7px 10px', color:'#c0392b' }}>₹{fmt(r.max_price)}</td>
                      <td style={{ padding:'7px 10px' }}>
                        <span style={{ background: r.labels_printed==r.total_lots?'#dcfce7':'#fef9c3', color: r.labels_printed==r.total_lots?'#166534':'#854d0e', padding:'2px 8px', borderRadius:99, fontSize:11 }}>
                          {r.labels_printed}/{r.total_lots}
                        </span>
                      </td>
                      <td style={{ padding:'7px 10px', color:'#1a7a4a' }}>{r.confirmed}</td>
                      <td style={{ padding:'7px 10px', color:'#c0392b' }}>{r.skipped}</td>
                    </tr>
                  ))}
                </tbody>
                {summary.length > 0 && (
                  <tfoot>
                    <tr style={{ background:'#1a3c5e', color:'#fff', fontWeight:700 }}>
                      <td style={{ padding:'8px 10px' }} colSpan={2}>TOTAL</td>
                      <td style={{ padding:'8px 10px' }}>{summary.reduce((a,b) => a+parseInt(b.total_lots),0)}</td>
                      <td style={{ padding:'8px 10px' }}>{fmtN(summary.reduce((a,b) => a+(parseFloat(b.total_bags)||0),0))}</td>
                      <td style={{ padding:'8px 10px' }}>{fmtN(summary.reduce((a,b) => a+(parseFloat(b.total_net_wt)||0),0))}</td>
                      <td colSpan={6} style={{ padding:'8px 10px' }}></td>
                    </tr>
                  </tfoot>
                )}
              </table>
            </div>
          )}
        </Card>
      )}

      {tab === 'garden' && (
        <Card style={{ borderRadius:'0 8px 8px 8px', marginTop:0 }}>
          {byGarden.length === 0 ? (
            <div style={{ padding:24, textAlign:'center', color:'#aaa' }}>Click Generate Report to load data</div>
          ) : (
            <div style={{ overflowX:'auto' }}>
              <table style={{ width:'100%', borderCollapse:'collapse', fontSize:13 }}>
                <thead>
                  <tr style={{ background:'#f0f4f8' }}>
                    {['Garden','Grade','Lots','Bags','Net Wt','Avg Price','Parties'].map(h => (
                      <th key={h} style={{ padding:'8px 10px', textAlign:'left', fontWeight:600, borderBottom:'2px solid #e2e8f0' }}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {byGarden.map((r, i) => (
                    <tr key={i} style={{ borderBottom:'1px solid #f0f4f8', background: i%2===0?'#fff':'#fafbfc' }}>
                      <td style={{ padding:'7px 10px', fontWeight:600 }}>{r.garden}</td>
                      <td style={{ padding:'7px 10px' }}>
                        <span style={{ background:'#dbeafe', color:'#1e40af', padding:'2px 8px', borderRadius:99, fontSize:11, fontWeight:600 }}>{r.grade}</span>
                      </td>
                      <td style={{ padding:'7px 10px' }}>{r.lots}</td>
                      <td style={{ padding:'7px 10px' }}>{fmtN(r.bags)}</td>
                      <td style={{ padding:'7px 10px' }}>{fmtN(r.net_wt)} kg</td>
                      <td style={{ padding:'7px 10px', fontWeight:600, color:'#1a3c5e' }}>₹{fmt(r.avg_price)}</td>
                      <td style={{ padding:'7px 10px', fontSize:11, color:'#888', maxWidth:200, overflow:'hidden', textOverflow:'ellipsis' }}>{r.parties}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </Card>
      )}
    </div>
  );
}
